INSERT INTO [HBE_SIM_BUILTIN_SCENE] ([ID], [SCENE_KEY], [NAME], [DESCRIPTION], [CATEGORY], [THUMBNAIL_URL], [ORDER_INDEX], [IS_ACTIVE], [CREATED_AT]) VALUES (1, N'construction', N'Công trường xây dựng', N'Cảnh ngoài trời: nhà đang xây, giàn giáo, cẩu tháp, bãi vật liệu, đường xe chạy. Hợp với kịch bản kiểm tra hiện trường (an toàn lao động, chất lượng thi công) — học viên đi quanh công trường tự tìm điểm nguy cơ, thứ tự xử lý không quan trọng.', N'Bối cảnh dựng sẵn', N'/uploads/sim-library/thumbnail/901f54d5c316444e94c0096afa5c5408.png', 1, 1, '2026-08-24T08:44:56.3505423');
INSERT INTO [HBE_SIM_BUILTIN_SCENE] ([ID], [SCENE_KEY], [NAME], [DESCRIPTION], [CATEGORY], [THUMBNAIL_URL], [ORDER_INDEX], [IS_ACTIVE], [CREATED_AT]) VALUES (2, N'hr-office', N'Văn phòng phòng Nhân sự', N'Cảnh trong nhà: quầy lễ tân, bàn tuyển dụng, phòng phỏng vấn, phòng họp, tủ hồ sơ, khu onboarding. Hợp với kịch bản QUY TRÌNH (tuyển dụng, tiếp nhận nhân viên mới, xử lý hồ sơ) — các bước phải làm theo đúng thứ tự.', N'Bối cảnh dựng sẵn', N'/uploads/sim-library/thumbnail/45f160aedaf3411791b71668f1dc14f5.png', 2, 1, '2026-08-24T08:44:56.3531674');
