INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1128, N'index.muted', N'vi', N'Bao phủ toàn bộ quy trình đào tạo, từ khâu soạn giảng, thiết kế học liệu đến báo cáo tổng quan.', N'Bao phủ toàn bộ quy trình đào tạo, từ khâu soạn giảng, thiết kế học liệu đến báo cáo tổng quan.', 1, NULL, NULL, NULL, '2026-08-24T09:32:58.8411845');
