INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1130, N'index.muted2', N'vi', N'Soạn nội dung phong phú: văn bản, tài liệu, hình ảnh, video. Thiết lập thời lượng, điểm chuẩn và hạn hoàn thành riêng biệt.', N'Soạn nội dung phong phú: văn bản, tài liệu, hình ảnh, video. Thiết lập thời lượng, điểm chuẩn và hạn hoàn thành riêng biệt.', 1, NULL, NULL, NULL, '2026-08-24T09:32:58.8411847');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1131, N'index.h4', N'vi', N'Phân bổ theo cấu trúc', N'Phân bổ theo cấu trúc', 1, NULL, NULL, NULL, '2026-08-24T09:32:58.8411848');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1132, N'index.muted3', N'vi', N'Gán khóa học chính xác theo từng phòng ban & vị trí công tác. Tối ưu hóa trải nghiệm cá nhân của mỗi nhân viên.', N'Gán khóa học chính xác theo từng phòng ban & vị trí công tác. Tối ưu hóa trải nghiệm cá nhân của mỗi nhân viên.', 1, NULL, NULL, NULL, '2026-08-24T09:32:58.8411849');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1133, N'index.h5', N'vi', N'Lộ trình học tập tuần tự', N'Lộ trình học tập tuần tự', 1, NULL, NULL, NULL, '2026-08-24T09:32:58.841185');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1134, N'index.muted4', N'vi', N'Khóa học dạng chuỗi bắt buộc. Người học phải hoàn thành điều kiện trước mới có thể tiếp cận nội dung tiếp theo.', N'Khóa học dạng chuỗi bắt buộc. Người học phải hoàn thành điều kiện trước mới có thể tiếp cận nội dung tiếp theo.', 1, NULL, NULL, NULL, '2026-08-24T09:32:58.8411851');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1135, N'index.h6', N'vi', N'Kiểm tra & đánh giá', N'Kiểm tra & đánh giá', 1, NULL, NULL, NULL, '2026-08-24T09:32:58.8411852');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1136, N'index.muted5', N'vi', N'Ngân hàng câu hỏi đa dạng (Trắc nghiệm, Multi-choice, True/False). Hệ thống chấm điểm tự động và chống gian lận.', N'Ngân hàng câu hỏi đa dạng (Trắc nghiệm, Multi-choice, True/False). Hệ thống chấm điểm tự động và chống gian lận.', 1, NULL, NULL, NULL, '2026-08-24T09:32:58.8411853');
