INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1138, N'index.muted6', N'vi', N'Ghi nhận chính xác số phút học, vị trí video đang xem dở và cập nhật tiến độ học tập liên tục lên Dashboard.', N'Ghi nhận chính xác số phút học, vị trí video đang xem dở và cập nhật tiến độ học tập liên tục lên Dashboard.', 1, NULL, NULL, NULL, '2026-08-24T09:32:58.8411855');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1139, N'index.h8', N'vi', N'Chứng nhận & QR Code', N'Chứng nhận & QR Code', 1, NULL, NULL, NULL, '2026-08-24T09:32:58.8411856');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1140, N'index.muted7', N'vi', N'Tự động sinh chứng chỉ cấp doanh nghiệp khi đạt chuẩn đầu ra. Cho phép bất kỳ ai cũng có thể quét QR xác thực.', N'Tự động sinh chứng chỉ cấp doanh nghiệp khi đạt chuẩn đầu ra. Cho phép bất kỳ ai cũng có thể quét QR xác thực.', 1, NULL, NULL, NULL, '2026-08-24T09:32:58.8411857');
