INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1871, N'role.adminLuonToanQuyen', N'vi', N'Vai trò Admin luôn giữ trọn quyền để không tự khóa mình khỏi trang phân quyền — phần tick bên trên chỉ để xem.', N'Vai trò Admin luôn giữ trọn quyền để không tự khóa mình khỏi trang phân quyền — phần tick bên trên chỉ để xem.', 1, NULL, NULL, NULL, '2026-08-24T09:32:58.8413006');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1872, N'role.tickONgoaiDeCapCaNhom', N'vi', N'Tick ô ngoài để cấp cả nhóm, bấm mũi tên để mở chi tiết Xem / Thêm / Sửa / Xóa. Quyền cấp riêng cho từng người ở trang Người dùng chỉ thu hẹp thêm, không mở rộng quá quyền của vai trò.', N'Tick ô ngoài để cấp cả nhóm, bấm mũi tên để mở chi tiết Xem / Thêm / Sửa / Xóa. Quyền cấp riêng cho từng người ở trang Người dùng chỉ thu hẹp thêm, không mở rộng quá quyền của vai trò.', 1, NULL, NULL, NULL, '2026-08-24T09:32:58.8413007');
