INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1918, N'translation.khoaDichHint', N'vi', N'Chỉ dùng chữ không dấu, số và các dấu . - _ — đặt theo dạng "nhóm.tenGoi" để dễ tìm sau này. Đây là mã kỹ thuật mà lập trình viên gắn vào giao diện, không phải chữ người dùng nhìn thấy.', N'Chỉ dùng chữ không dấu, số và các dấu . - _ — đặt theo dạng "nhóm.tenGoi" để dễ tìm sau này. Đây là mã kỹ thuật mà lập trình viên gắn vào giao diện, không phải chữ người dùng nhìn thấy.', 1, NULL, NULL, NULL, '2026-08-24T09:32:58.8413096');
