INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1920, N'translation.ghiChuHint', N'vi', N'Ghi lại vì sao chọn cách dịch này — người sau đọc sẽ không tưởng là dịch sai rồi sửa ngược lại.', N'Ghi lại vì sao chọn cách dịch này — người sau đọc sẽ không tưởng là dịch sai rồi sửa ngược lại.', 1, NULL, NULL, NULL, '2026-08-24T09:32:58.8413099');
