INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1939, N'translation.theLocaleHint', N'en', N'Decides whose conventions dates and numbers follow (25/12/2026 versus 12/25/2026). Leaving it blank is fine.', N'Decides whose conventions dates and numbers follow (25/12/2026 versus 12/25/2026). Leaving it blank is fine.', 1, NULL, NULL, NULL, '2026-08-24T09:51:10.8918732');
