INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1949, N'translation.maNgonNguHint', N'vi', N'Mã 2 chữ cái theo chuẩn quốc tế của ngôn ngữ đó (tra "mã ISO 639-1" nếu chưa rõ). Hệ thống dùng mã này để lưu bản dịch nên thêm xong không đổi được.', N'Mã 2 chữ cái theo chuẩn quốc tế của ngôn ngữ đó (tra "mã ISO 639-1" nếu chưa rõ). Hệ thống dùng mã này để lưu bản dịch nên thêm xong không đổi được.', 1, NULL, NULL, NULL, '2026-08-24T09:51:10.9079577');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1950, N'translation.tenHienThi', N'vi', N'Tên gọi hiển thị *', N'Tên gọi hiển thị *', 1, NULL, NULL, NULL, '2026-08-24T09:51:10.9079582');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1951, N'translation.tenHienThiHint', N'vi', N'Tên này xuất hiện ở đầu cột trong bảng dịch và khi người dùng đổi ngôn ngữ. Thường viết bằng chính tiếng đó để người bản xứ nhận ra, nhưng bạn sửa lại thành "Tiếng Nhật" cũng được.', N'Tên này xuất hiện ở đầu cột trong bảng dịch và khi người dùng đổi ngôn ngữ. Thường viết bằng chính tiếng đó để người bản xứ nhận ra, nhưng bạn sửa lại thành "Tiếng Nhật" cũng được.', 1, NULL, NULL, NULL, '2026-08-24T09:51:10.9079585');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1952, N'translation.theLocale', N'vi', N'Kiểu hiển thị ngày và số', N'Kiểu hiển thị ngày và số', 1, NULL, NULL, NULL, '2026-08-24T09:51:10.9079588');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1953, N'translation.theLocaleHint', N'vi', N'Quyết định ngày tháng và con số hiện theo thói quen nước nào (VD 25/12/2026 hay 12/25/2026). Bỏ trống cũng được.', N'Quyết định ngày tháng và con số hiện theo thói quen nước nào (VD 25/12/2026 hay 12/25/2026). Bỏ trống cũng được.', 1, NULL, NULL, NULL, '2026-08-24T09:51:10.9079592');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1954, N'translation.dichTamTu', N'vi', N'Bắt đầu từ bản dịch nào', N'Bắt đầu từ bản dịch nào', 1, NULL, NULL, NULL, '2026-08-24T09:51:10.9079597');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1955, N'translation.dichTamTuHint', N'vi', N'Ngôn ngữ mới cần có sẵn chữ để bạn sửa dần. Chọn "Tiếng Việt" thì bảng dịch có đủ các dòng bằng tiếng Việt, bạn sửa dòng nào thì dòng đó thành tiếng mới. Chọn "Để trống" thì bảng dịch rỗng, và chỗ nào chưa dịch sẽ hiện tạm tiếng Việt.', N'Ngôn ngữ mới cần có sẵn chữ để bạn sửa dần. Chọn "Tiếng Việt" thì bảng dịch có đủ các dòng bằng tiếng Việt, bạn sửa dòng nào thì dòng đó thành tiếng mới. Chọn "Để trống" thì bảng dịch rỗng, và chỗ nào chưa dịch sẽ hiện tạm tiếng Việt.', 1, NULL, NULL, NULL, '2026-08-24T09:51:10.90796');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (1956, N'translation.khongChep', N'vi', N'Để trống, tự nhập từ đầu', N'Để trống, tự nhập từ đầu', 1, NULL, NULL, NULL, '2026-08-24T09:51:10.9079602');
