INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (2121, N'index.muted', N'ar', N'Bao phủ toàn bộ quy trình đào tạo, từ khâu soạn giảng, thiết kế học liệu đến báo cáo tổng quan.', NULL, 1, NULL, 1, '2026-08-24T10:08:12.2701106', '2026-08-24T10:08:12.2701099');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (2122, N'index.h3', N'ar', N'Quản lý khóa học & bài học', NULL, 1, NULL, 1, '2026-08-24T10:08:12.2701257', '2026-08-24T10:08:12.270124');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (2123, N'index.muted2', N'ar', N'Soạn nội dung phong phú: văn bản, tài liệu, hình ảnh, video. Thiết lập thời lượng, điểm chuẩn và hạn hoàn thành riêng biệt.', NULL, 1, NULL, 1, '2026-08-24T10:08:12.27014', '2026-08-24T10:08:12.2701392');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (2124, N'index.h4', N'ar', N'Phân bổ theo cấu trúc', NULL, 1, NULL, 1, '2026-08-24T10:08:12.270154', '2026-08-24T10:08:12.2701532');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (2125, N'index.muted3', N'ar', N'Gán khóa học chính xác theo từng phòng ban & vị trí công tác. Tối ưu hóa trải nghiệm cá nhân của mỗi nhân viên.', NULL, 1, NULL, 1, '2026-08-24T10:08:12.2701681', '2026-08-24T10:08:12.2701674');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (2126, N'index.h5', N'ar', N'Lộ trình học tập tuần tự', NULL, 1, NULL, 1, '2026-08-24T10:08:12.2701826', '2026-08-24T10:08:12.2701818');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (2127, N'index.muted4', N'ar', N'Khóa học dạng chuỗi bắt buộc. Người học phải hoàn thành điều kiện trước mới có thể tiếp cận nội dung tiếp theo.', NULL, 1, NULL, 1, '2026-08-24T10:08:12.2701966', '2026-08-24T10:08:12.2701958');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (2128, N'index.h6', N'ar', N'Kiểm tra & đánh giá', NULL, 1, NULL, 1, '2026-08-24T10:08:12.2702108', '2026-08-24T10:08:12.2702101');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (2129, N'index.muted5', N'ar', N'Ngân hàng câu hỏi đa dạng (Trắc nghiệm, Multi-choice, True/False). Hệ thống chấm điểm tự động và chống gian lận.', NULL, 1, NULL, 1, '2026-08-24T10:08:12.2702257', '2026-08-24T10:08:12.2702249');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (2130, N'index.h7', N'ar', N'Theo dõi thời gian thực', NULL, 1, NULL, 1, '2026-08-24T10:08:12.2702396', '2026-08-24T10:08:12.2702389');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (2131, N'index.muted6', N'ar', N'Ghi nhận chính xác số phút học, vị trí video đang xem dở và cập nhật tiến độ học tập liên tục lên Dashboard.', NULL, 1, NULL, 1, '2026-08-24T10:08:12.2702533', '2026-08-24T10:08:12.2702526');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (2132, N'index.h8', N'ar', N'Chứng nhận & QR Code', NULL, 1, NULL, 1, '2026-08-24T10:08:12.2702678', '2026-08-24T10:08:12.2702669');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (2133, N'index.muted7', N'ar', N'Tự động sinh chứng chỉ cấp doanh nghiệp khi đạt chuẩn đầu ra. Cho phép bất kỳ ai cũng có thể quét QR xác thực.', NULL, 1, NULL, 1, '2026-08-24T10:08:12.2702814', '2026-08-24T10:08:12.2702806');
INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (2134, N'index.metaDesc', N'ar', N'Nền tảng E-Learning quản lý toàn bộ vòng đời đào tạo nội bộ: xây dựng khóa học, lộ trình học tập, kiểm tra đánh giá và cấp chứng nhận xác thực bằng QR Code.', NULL, 1, NULL, 1, '2026-08-24T10:08:12.2702948', '2026-08-24T10:08:12.270294');
