INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (2932, N'translation.theLocaleHint', N'ar', N'Quyết định cách hiện ngày tháng và con số. Bỏ trống thì dùng chính mã ngôn ngữ.', NULL, 1, NULL, 1, '2026-08-24T10:08:12.2816079', '2026-08-24T10:08:12.2816073');
