INSERT INTO [HBE_TRANSLATION] ([ID], [RESOURCE_KEY], [LANG], [TRANSLATED_TEXT], [DEFAULT_TEXT], [IS_SYSTEM], [NOTE], [UPDATED_BY_ID], [UPDATED_AT], [CREATED_AT]) VALUES (2934, N'translation.dichTamTuHint', N'ar', N'Chép toàn bộ câu chữ của ngôn ngữ đã chọn sang ngôn ngữ mới để có cái mà sửa dần. Bắt đầu từ bảng trống thì mọi màn hình sẽ trơ chữ dự phòng cho tới khi có người dịch.', NULL, 1, NULL, 1, '2026-08-24T10:08:12.2816325', '2026-08-24T10:08:12.2816318');
