INSERT INTO [HBE_QUESTION] ([ID], [QUIZ_ID], [CONTENT], [QUESTION_TYPE], [SCORE], [ORDER_INDEX], [EXPLANATION]) VALUES (63, 11, N'Đâu là một trong những nguyên nhân phổ biến nhất gây chập cháy điện tại môi trường văn phòng?', 0, 1.0, 1, N'Các thói quen này đều dẫn đến quá tải hoặc phát sinh nhiệt gây cháy nổ.');
INSERT INTO [HBE_QUESTION] ([ID], [QUIZ_ID], [CONTENT], [QUESTION_TYPE], [SCORE], [ORDER_INDEX], [EXPLANATION]) VALUES (64, 11, N'Tại nơi làm việc, hành động nào sau đây giúp giảm thiểu tối đa nguy cơ cháy nổ từ các thiết bị điện trước khi ra về?', 0, 1.0, 2, N'Rút phích cắm/tắt công tắc ngắt hẳn nguồn điện giúp loại bỏ hoàn toàn nguy cơ chập mạch điện khi không có người.');
INSERT INTO [HBE_QUESTION] ([ID], [QUIZ_ID], [CONTENT], [QUESTION_TYPE], [SCORE], [ORDER_INDEX], [EXPLANATION]) VALUES (65, 11, N'Việc hút thuốc lá tại nơi làm việc cần tuân thủ quy định nào để không trở thành nguy cơ gây cháy?', 0, 1.0, 3, N'Tuyệt đối tuân thủ các quy định về hút thuốc để tránh tàn lửa bắt vào các vật liệu dễ cháy.');
INSERT INTO [HBE_QUESTION] ([ID], [QUIZ_ID], [CONTENT], [QUESTION_TYPE], [SCORE], [ORDER_INDEX], [EXPLANATION]) VALUES (66, 11, N'Khi phát hiện đám cháy tại doanh nghiệp, số điện thoại khẩn cấp và trực tiếp nhất cần gọi ngay để báo Cảnh sát PCCC & CNCH là số nào?', 0, 1.0, 4, N'114 là tổng đài của Cảnh sát Phòng cháy chữa cháy và Cứu nạn cứu hộ.');
INSERT INTO [HBE_QUESTION] ([ID], [QUIZ_ID], [CONTENT], [QUESTION_TYPE], [SCORE], [ORDER_INDEX], [EXPLANATION]) VALUES (67, 11, N'Hành động ưu tiên đầu tiên ngay khi bạn phát hiện một đám cháy nhỏ mới phát sinh là gì?', 0, 1.0, 5, N'Báo động ngay giúp mọi người kịp thời phản ứng, thoát nạn an toàn và huy động người đến hỗ trợ dập lửa.');
INSERT INTO [HBE_QUESTION] ([ID], [QUIZ_ID], [CONTENT], [QUESTION_TYPE], [SCORE], [ORDER_INDEX], [EXPLANATION]) VALUES (68, 11, N'Nếu đám cháy đã bùng phát lớn, khói đen dày đặc và vượt quá khả năng kiểm soát của bình chữa cháy xách tay, bạn cần làm gì?', 0, 1.0, 6, N'Cúi thấp người giúp bạn tránh hít phải khí độc và khói nóng (thường bay lên cao).');
INSERT INTO [HBE_QUESTION] ([ID], [QUIZ_ID], [CONTENT], [QUESTION_TYPE], [SCORE], [ORDER_INDEX], [EXPLANATION]) VALUES (69, 11, N'Đặc điểm nhận dạng nhanh nhất bằng mắt thường để phân biệt Bình bột chữa cháy và Bình khí CO2 là gì?', 0, 1.0, 7, N'Đồng hồ đo áp suất là dấu hiệu dễ nhận biết nhất trên bình bột, còn bình khí CO2 thì không có chi tiết này.');
INSERT INTO [HBE_QUESTION] ([ID], [QUIZ_ID], [CONTENT], [QUESTION_TYPE], [SCORE], [ORDER_INDEX], [EXPLANATION]) VALUES (70, 11, N'Đối với đám cháy tại Phòng Server (Máy chủ) hoặc khu vực có nhiều vi mạch điện tử đắt tiền, bạn NÊN ưu tiên sử dụng loại bình nào và KHÔNG NÊN dùng loại nào?', 0, 1.0, 8, N'Bình CO2 dập lửa sạch, bay hơi hết. Còn bình bột để lại cặn có tính ăn mòn nhẹ làm hỏng đồ điện tử tinh vi.');
INSERT INTO [HBE_QUESTION] ([ID], [QUIZ_ID], [CONTENT], [QUESTION_TYPE], [SCORE], [ORDER_INDEX], [EXPLANATION]) VALUES (71, 11, N'Khi sử dụng bình chữa cháy khí CO2, người dùng tuyệt đối KHÔNG được cầm tay vào bộ phận nào của bình để tránh bị bỏng lạnh (-79°C)?', 0, 1.0, 9, N'Khí CO2 khi phun ra có nhiệt độ rất thấp (-79 độ C), có thể gây bỏng lạnh hoại tử nếu cầm trực tiếp vào loa phun.');
INSERT INTO [HBE_QUESTION] ([ID], [QUIZ_ID], [CONTENT], [QUESTION_TYPE], [SCORE], [ORDER_INDEX], [EXPLANATION]) VALUES (72, 11, N'Theo quy tắc sử dụng bình chữa cháy P.A.S.S, khi tiến hành xịt (bước Aim - Hướng vòi), bạn cần hướng vòi phun vào vị trí nào của đám cháy?', 0, 1.0, 10, N'Hướng vào gốc lửa (nơi bắt nguồn sự cháy) sẽ cắt đứt nguồn ôxy và làm giảm nhiệt chất cháy hiệu quả nhất.');
INSERT INTO [HBE_QUESTION] ([ID], [QUIZ_ID], [CONTENT], [QUESTION_TYPE], [SCORE], [ORDER_INDEX], [EXPLANATION]) VALUES (73, 12, N'Đâu là một trong những nguyên nhân phổ biến nhất gây chập cháy điện tại môi trường văn phòng?', 0, 1.0, 1, N'Các thói quen này đều dẫn đến quá tải hoặc phát sinh nhiệt gây cháy nổ.');
INSERT INTO [HBE_QUESTION] ([ID], [QUIZ_ID], [CONTENT], [QUESTION_TYPE], [SCORE], [ORDER_INDEX], [EXPLANATION]) VALUES (74, 12, N'Tại nơi làm việc, hành động nào sau đây giúp giảm thiểu tối đa nguy cơ cháy nổ từ các thiết bị điện trước khi ra về?', 0, 1.0, 2, N'Rút phích cắm/tắt công tắc ngắt hẳn nguồn điện giúp loại bỏ hoàn toàn nguy cơ chập mạch điện khi không có người.');
INSERT INTO [HBE_QUESTION] ([ID], [QUIZ_ID], [CONTENT], [QUESTION_TYPE], [SCORE], [ORDER_INDEX], [EXPLANATION]) VALUES (75, 12, N'Việc hút thuốc lá tại nơi làm việc cần tuân thủ quy định nào để không trở thành nguy cơ gây cháy?', 0, 1.0, 3, N'Tuyệt đối tuân thủ các quy định về hút thuốc để tránh tàn lửa bắt vào các vật liệu dễ cháy.');
INSERT INTO [HBE_QUESTION] ([ID], [QUIZ_ID], [CONTENT], [QUESTION_TYPE], [SCORE], [ORDER_INDEX], [EXPLANATION]) VALUES (76, 12, N'Khi phát hiện đám cháy tại doanh nghiệp, số điện thoại khẩn cấp và trực tiếp nhất cần gọi ngay để báo Cảnh sát PCCC & CNCH là số nào?', 0, 1.0, 4, N'114 là tổng đài của Cảnh sát Phòng cháy chữa cháy và Cứu nạn cứu hộ.');
INSERT INTO [HBE_QUESTION] ([ID], [QUIZ_ID], [CONTENT], [QUESTION_TYPE], [SCORE], [ORDER_INDEX], [EXPLANATION]) VALUES (77, 12, N'Hành động ưu tiên đầu tiên ngay khi bạn phát hiện một đám cháy nhỏ mới phát sinh là gì?', 0, 1.0, 5, N'Báo động ngay giúp mọi người kịp thời phản ứng, thoát nạn an toàn và huy động người đến hỗ trợ dập lửa.');
INSERT INTO [HBE_QUESTION] ([ID], [QUIZ_ID], [CONTENT], [QUESTION_TYPE], [SCORE], [ORDER_INDEX], [EXPLANATION]) VALUES (78, 12, N'Nếu đám cháy đã bùng phát lớn, khói đen dày đặc và vượt quá khả năng kiểm soát của bình chữa cháy xách tay, bạn cần làm gì?', 0, 1.0, 6, N'Cúi thấp người giúp bạn tránh hít phải khí độc và khói nóng (thường bay lên cao).');
